package com.global.ct.frameinventory.inventoryimport;

import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.regex.Pattern;

import io.grpc.Context;
import io.grpc.Contexts;
import io.grpc.Grpc;
import io.grpc.Metadata;
import io.grpc.ServerCall;
import io.grpc.ServerCallHandler;
import io.grpc.ServerInterceptor;
import io.grpc.Status;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.env.Environment;
import org.springframework.core.env.Profiles;
import org.springframework.stereotype.Component;

/** Service-scoped authentication for the local import exercise. */
@Component
public final class LocalImportIdentity implements ServerInterceptor {
    private static final Metadata.Key<String> AUTHORIZATION =
            Metadata.Key.of("authorization", Metadata.ASCII_STRING_MARSHALLER);
    private static final Context.Key<String> OPERATOR = Context.key("import-operator");
    private static final Pattern TOKEN = Pattern.compile("[a-f0-9]{64}");

    private final boolean enabled;
    private final byte[] expectedAuthorization;

    public LocalImportIdentity(
            Environment environment,
            @Value("${inventory.import.local-token:}") String token) {
        enabled = environment.acceptsProfiles(Profiles.of("local-import"));
        if (enabled && !TOKEN.matcher(token).matches()) {
            throw new IllegalArgumentException("Local import requires a 64-character lowercase hex token");
        }
        expectedAuthorization = ("Bearer " + token).getBytes(StandardCharsets.US_ASCII);
    }

    public static String requireOperator() {
        String operator = OPERATOR.get();
        if (operator == null) {
            throw Status.UNAUTHENTICATED.asRuntimeException();
        }
        return operator;
    }

    public static void requireJobOwner(String owner) {
        if (!requireOperator().equals(owner)) {
            throw Status.PERMISSION_DENIED.asRuntimeException();
        }
    }

    @Override
    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
            ServerCall<ReqT, RespT> call, Metadata headers, ServerCallHandler<ReqT, RespT> next) {
        if (!enabled) {
            call.close(Status.UNAVAILABLE.withDescription("Local imports are disabled"), new Metadata());
            return new ServerCall.Listener<>() {};
        }
        var peer = call.getAttributes().get(Grpc.TRANSPORT_ATTR_REMOTE_ADDR);
        String authorization = headers.get(AUTHORIZATION);
        if (!(peer instanceof InetSocketAddress socket) || socket.getAddress() == null
                || !socket.getAddress().isLoopbackAddress() || authorization == null
                || !MessageDigest.isEqual(expectedAuthorization, authorization.getBytes(StandardCharsets.US_ASCII))) {
            call.close(Status.UNAUTHENTICATED, new Metadata());
            return new ServerCall.Listener<>() {};
        }
        return Contexts.interceptCall(Context.current().withValue(OPERATOR, "local-import-operator"),
                call, headers, next);
    }
}
package com.global.ct.frameinventory.inventoryimport;

import java.time.Duration;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;

@Service
@Profile("local-import")
class ImportJobService {
    private static final Duration DISPATCH_GRACE = Duration.ofMinutes(15);
    private final ImportJobRepository jobs;
    private final ImportUploadSigner signer;
    private final String bucket;

    ImportJobService(ImportJobRepository jobs, ImportUploadSigner signer,
                     @Value("${inventory.import.bucket:}") String bucket) {
        this.jobs = jobs;
        this.signer = signer;
        this.bucket = bucket;
    }

    CreatedJob create(String owner, boolean forceOverwrite) {
        if (bucket.isBlank()) {
            throw new ImportJobProblem(ImportJobProblem.Code.NOT_CONFIGURED);
        }
        UUID id = UUID.randomUUID();
        String key = "uploads/" + id + "/inventory_frame.csv";
        var signed = signer.sign(bucket, key);
        var headers = new LinkedHashMap<String, String>();
        signed.signedHeaders().forEach((name, values) -> {
            if (!name.equalsIgnoreCase("host")) {
                headers.put(name, String.join(",", values));
            }
        });
        var expires = signed.expiration();
        var job = jobs.create(id, owner, forceOverwrite, bucket, key, expires, expires.plus(DISPATCH_GRACE));
        return new CreatedJob(job, signed.url().toExternalForm(), Map.copyOf(headers));
    }

    ImportJobRepository.Job get(UUID id, String owner) {
        jobs.expireOwnedUpload(id, owner);
        return jobs.findOwned(id, owner).orElseThrow(() -> new ImportJobProblem(ImportJobProblem.Code.NOT_FOUND));
    }

    ErrorPage errors(UUID id, String owner, int page, int size) {
        get(id, owner);
        var rows = jobs.errors(id, (long) page * size, size + 1);
        return new ErrorPage(rows.subList(0, Math.min(size, rows.size())), rows.size() > size);
    }

    record CreatedJob(ImportJobRepository.Job job, String url, Map<String, String> headers) {}
    record ErrorPage(List<ImportJobRepository.RowError> items, boolean hasNext) {}
}
