@Configuration(proxyBeanMethods = false)
@Profile("local-import")
@ConditionalOnProperty(name = {"inventory.import.dispatch.enabled", "inventory.import.worker.enabled"},
    havingValue = "true")
class CsvImportWorkerConfiguration {
    @Bean(initMethod = "start", destroyMethod = "shutdown")
    WorkerFactory importWorker(WorkflowClient temporal, ImportStaging staging, ImportDeltaApply delta,
                               InventoryCsvReader reader, S3Client s3, MeterRegistry registry,
                               @Value("${inventory.import.dispatch.task-queue:inventory-import}") String taskQueue) {
        var factory = WorkerFactory.newInstance(temporal);
        var worker = factory.newWorker(taskQueue);
        worker.registerWorkflowImplementationTypes(CsvImportWorkflow.Implementation.class);
        var applyDuration = Timer.builder("inventory.import.apply")
            .description("Time spent in each import apply activity attempt")
            .publishPercentileHistogram()
            .register(registry);
        worker.registerActivitiesImplementations(new CsvImportActivities(staging, delta, reader, s3, applyDuration));
        return factory;
    }
}
package com.global.ct.frameinventory.inventoryimport;

import java.time.Duration;
import java.time.Instant;
import java.util.UUID;
import java.util.concurrent.TimeUnit;

import io.grpc.Status;
import io.grpc.StatusRuntimeException;
import io.temporal.api.common.v1.WorkflowExecution;
import io.temporal.api.enums.v1.WorkflowIdConflictPolicy;
import io.temporal.api.enums.v1.WorkflowIdReusePolicy;
import io.temporal.api.workflowservice.v1.DescribeWorkflowExecutionRequest;
import io.temporal.client.WorkflowClient;
import io.temporal.client.WorkflowExecutionAlreadyStarted;
import io.temporal.client.WorkflowOptions;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Profile("local-import")
@ConditionalOnProperty(name = "inventory.import.dispatch.enabled", havingValue = "true")
class ImportTemporalDispatch {
    private final ImportJobRepository jobs;
    private final WorkflowClient temporal;
    private final String taskQueue;

    ImportTemporalDispatch(ImportJobRepository jobs, WorkflowClient temporal,
                           @Value("${inventory.import.dispatch.task-queue:inventory-import}") String taskQueue) {
        this.jobs = jobs;
        this.temporal = temporal;
        this.taskQueue = taskQueue;
    }

    @Transactional
    public void start(S3ImportNotifications.Upload upload) {
        var job = jobs.lockBoundUpload(upload.jobId(), upload.version());
        if (job.isEmpty() || !job.get().status().equals("PENDING") || job.get().dispatchConfirmedAt() != null) {
            return;
        }
        var options = WorkflowOptions.newBuilder().setWorkflowId(workflowId(upload.jobId()))
            .setTaskQueue(taskQueue)
            .setWorkflowIdConflictPolicy(WorkflowIdConflictPolicy.WORKFLOW_ID_CONFLICT_POLICY_USE_EXISTING)
            .setWorkflowIdReusePolicy(WorkflowIdReusePolicy.WORKFLOW_ID_REUSE_POLICY_REJECT_DUPLICATE)
            .setWorkflowExecutionTimeout(Duration.ofHours(1))
            .build();
        try {
            temporal.newUntypedWorkflowStub("CsvImportWorkflow", options).start(upload.jobId().toString());
        } catch (WorkflowExecutionAlreadyStarted duplicate) {
            // The stable ID already belongs to this job, even if the execution has closed.
        }
        jobs.confirmDispatch(upload.jobId(), upload.version());
    }

    @Transactional
    public void reconcileDeadLetter(S3ImportNotifications.Upload upload) {
        var job = jobs.lockBoundUpload(upload.jobId(), upload.version());
        if (job.isEmpty() || !job.get().status().equals("PENDING") || job.get().dispatchConfirmedAt() != null) {
            return;
        }
        var request = DescribeWorkflowExecutionRequest.newBuilder()
            .setNamespace(temporal.getOptions().getNamespace())
            .setExecution(WorkflowExecution.newBuilder().setWorkflowId(workflowId(upload.jobId())))
            .build();
        try {
            temporal.getWorkflowServiceStubs().blockingStub().withDeadlineAfter(5, TimeUnit.SECONDS)
                .describeWorkflowExecution(request);
            jobs.confirmDispatch(upload.jobId(), upload.version());
        } catch (StatusRuntimeException error) {
            if (error.getStatus().getCode() != Status.Code.NOT_FOUND) {
                throw error;
            }
            if (job.get().dispatchUntil().toInstant().isAfter(Instant.now())) {
                throw new DispatchStillReconciling();
            }
            jobs.failDispatch(upload.jobId(), upload.version());
        }
    }

    private static String workflowId(UUID jobId) {
        return "csv-import-" + jobId;
    }

    static final class DispatchStillReconciling extends RuntimeException {}
}

package com.global.ct.frameinventory.inventoryimport;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.ArrayList;
import java.util.UUID;

import io.micrometer.core.instrument.Timer;
import io.temporal.activity.Activity;
import io.temporal.failure.ApplicationFailure;
import software.amazon.awssdk.services.s3.S3Client;

public class CsvImportActivities implements CsvImportWorkflow.Activities {
    private static final long MAX_BYTES = 10L * 1024 * 1024;
    private static final int BATCH_SIZE = 200;

    private final ImportStaging staging;
    private final ImportDeltaApply delta;
    private final InventoryCsvReader reader;
    private final S3Client s3;
    private final Timer applyDuration;

    CsvImportActivities(ImportStaging staging, ImportDeltaApply delta, InventoryCsvReader reader, S3Client s3,
                        Timer applyDuration) {
        this.staging = staging;
        this.delta = delta;
        this.reader = reader;
        this.s3 = s3;
        this.applyDuration = applyDuration;
    }

    @Override
    public String stage(String jobId, int pass) {
        var context = Activity.getExecutionContext();
        UUID job = UUID.fromString(jobId);
        UUID generation = UUID.randomUUID();
        var claim = staging.claim(job, generation, pass * 10 + context.getInfo().getAttempt());
        if (claim.isEmpty()) {
            return "";
        }
        var object = claim.get();
        context.heartbeat(0);
        try (var stream = s3.getObject(request -> request.bucket(object.objectBucket())
                .key(object.objectKey()).versionId(object.objectVersionId()))) {
            if (stream.response().contentLength() > MAX_BYTES) {
                stream.abort();
                throw ApplicationFailure.newNonRetryableFailure("Upload exceeds 10 MiB", "UPLOAD_TOO_LARGE");
            }
            var batch = new ArrayList<InventoryCsvReader.Row>(BATCH_SIZE);
            int count = reader.read(stream, row -> {
                batch.add(row);
                if (batch.size() == BATCH_SIZE) {
                    staging.append(job, generation, batch);
                    batch.clear();
                    context.heartbeat(row.number());
                }
            });
            if (!batch.isEmpty()) {
                staging.append(job, generation, batch);
            }
            staging.complete(job, generation, count);
            context.heartbeat(count);
            return generation.toString();
        } catch (InventoryCsvReader.FileProblem invalid) {
            throw ApplicationFailure.newNonRetryableFailure("CSV validation failed", invalid.getMessage());
        } catch (IOException readFailure) {
            throw new UncheckedIOException(readFailure);
        }
    }

    @Override
    public boolean apply(String jobId, String generation) {
        return applyDuration.record(() -> delta.apply(UUID.fromString(jobId), UUID.fromString(generation)));
    }

    @Override
    public void fail(String jobId, String code) {
        delta.fail(UUID.fromString(jobId), code);
    }
}
package com.global.ct.frameinventory.inventoryimport;

import java.sql.Types;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

@Repository
class ImportStaging {
    private final JdbcClient jdbc;
    private final NamedParameterJdbcTemplate batches;

    ImportStaging(JdbcClient jdbc, NamedParameterJdbcTemplate batches) {
        this.jdbc = jdbc;
        this.batches = batches;
    }

    @Transactional
    public Optional<ObjectVersion> claim(UUID job, UUID generation, int sequence) {
        var input = jdbc.sql("""
                UPDATE import_jobs
                SET status = 'RUNNING', staging_generation = :generation, staging_sequence = :sequence
                WHERE job_id = :job AND status IN ('PENDING', 'RUNNING')
                  AND import_mode = 'DELTA' AND object_version_id IS NOT NULL AND staging_sequence < :sequence
                RETURNING object_bucket, object_key, object_version_id
                """).param("job", job).param("generation", generation).param("sequence", sequence)
            .query(ObjectVersion.class).optional();
        if (input.isPresent()) {
            clear(job);
        }
        return input;
    }

    @Transactional
    public void append(UUID job, UUID generation, List<InventoryCsvReader.Row> rows) {
        requireClaim(job, generation);
        batches.batchUpdate("""
            INSERT INTO stg_inventory_import (job_id, generation, row_number, frame_id, payload, error_code, error_detail)
            VALUES (:job, :generation, :number, :frame, CAST(:payload AS jsonb), :code, :detail)
            """, rows.stream().map(row -> new MapSqlParameterSource()
                .addValue("job", job).addValue("generation", generation).addValue("number", row.number())
                .addValue("frame", row.frameId(), Types.VARCHAR).addValue("payload", row.payload(), Types.VARCHAR)
                .addValue("code", row.errorCode(), Types.VARCHAR).addValue("detail", row.errorDetail(), Types.VARCHAR))
            .toArray(MapSqlParameterSource[]::new));
    }

    @Transactional
    public void complete(UUID job, UUID generation, int rows) {
        requireClaim(job, generation);
        jdbc.sql("""
                INSERT INTO stg_inventory_import_completion (job_id, generation, row_count)
                VALUES (:job, :generation, :rows)
                """).param("job", job).param("generation", generation).param("rows", rows).update();
    }

    void clear(UUID job) {
        jdbc.sql("DELETE FROM stg_inventory_import_completion WHERE job_id = :job").param("job", job).update();
        jdbc.sql("DELETE FROM stg_inventory_import WHERE job_id = :job").param("job", job).update();
    }

    private void requireClaim(UUID job, UUID generation) {
        if (jdbc.sql("""
                SELECT job_id FROM import_jobs
                WHERE job_id = :job AND status = 'RUNNING' AND staging_generation = :generation FOR UPDATE
                """).param("job", job).param("generation", generation).query(UUID.class).optional().isEmpty()) {
            throw new IllegalStateException("Import staging attempt no longer owns the job");
        }
    }

    record ObjectVersion(String objectBucket, String objectKey, String objectVersionId) {}
}
package com.global.ct.frameinventory.inventoryimport;

import java.time.OffsetDateTime;
import java.util.UUID;

import com.global.ct.frameinventory.grpc.v1.CreateImportJobRequest;
import com.global.ct.frameinventory.grpc.v1.CreateImportJobResponse;
import com.global.ct.frameinventory.grpc.v1.GetImportJobRequest;
import com.global.ct.frameinventory.grpc.v1.ImportJob;
import com.global.ct.frameinventory.grpc.v1.ImportJobStatus;
import com.global.ct.frameinventory.grpc.v1.ImportMode;
import com.global.ct.frameinventory.grpc.v1.ImportRowError;
import com.global.ct.frameinventory.grpc.v1.InventoryImportGrpc;
import com.global.ct.frameinventory.grpc.v1.ListImportRowErrorsRequest;
import com.global.ct.frameinventory.grpc.v1.ListImportRowErrorsResponse;
import com.google.protobuf.Timestamp;
import io.grpc.Status;
import io.grpc.stub.StreamObserver;
import org.springframework.context.annotation.Profile;
import org.springframework.grpc.server.service.GrpcService;

@GrpcService(interceptors = LocalImportIdentity.class, blendWithGlobalInterceptors = true)
@Profile("local-import")
class ImportGrpcService extends InventoryImportGrpc.InventoryImportImplBase {
    private final ImportJobService jobs;

    ImportGrpcService(ImportJobService jobs) {
        this.jobs = jobs;
    }

    @Override
    public void createImportJob(CreateImportJobRequest request, StreamObserver<CreateImportJobResponse> response) {
        String owner = LocalImportIdentity.requireOperator();
        switch (request.getMode()) {
            case FULL_SNAPSHOT -> throw Status.FAILED_PRECONDITION
                .withDescription("Full snapshot imports are disabled").asRuntimeException();
            case UNRECOGNIZED -> throw Status.INVALID_ARGUMENT
                .withDescription("Unsupported import mode").asRuntimeException();
            default -> { }
        }
        var upload = jobs.create(owner, request.getForceOverwrite());
        reply(response, CreateImportJobResponse.newBuilder().setJob(toProto(upload.job()))
            .setUploadUrl(upload.url()).putAllUploadHeaders(upload.headers()).build());
    }

    @Override
    public void getImportJob(GetImportJobRequest request, StreamObserver<ImportJob> response) {
        reply(response, toProto(jobs.get(jobId(request.getJobId()), LocalImportIdentity.requireOperator())));
    }

    @Override
    public void listImportRowErrors(ListImportRowErrorsRequest request,
                                    StreamObserver<ListImportRowErrorsResponse> response) {
        int page = request.getPage();
        int size = request.hasSize() ? request.getSize() : 25;
        if (page < 0 || size < 1 || size > 50) {
            throw Status.INVALID_ARGUMENT.withDescription("Page must be nonnegative and size must be 1–50")
                .asRuntimeException();
        }
        var errors = jobs.errors(jobId(request.getJobId()), LocalImportIdentity.requireOperator(), page, size);
        var result = ListImportRowErrorsResponse.newBuilder().setPage(page).setSize(size)
            .setHasNext(errors.hasNext());
        for (var row : errors.items()) {
            var error = ImportRowError.newBuilder().setRowNumber(row.rowNumber())
                .setCode(row.code()).setDetail(row.detail());
            if (row.frameId() != null) {
                error.setFrameId(row.frameId());
            }
            result.addItems(error);
        }
        reply(response, result.build());
    }

    private static UUID jobId(String value) {
        try {
            UUID id = UUID.fromString(value);
            if (id.toString().equalsIgnoreCase(value)) {
                return id;
            }
        } catch (IllegalArgumentException invalid) {
            // UUID.fromString also accepts abbreviated groups, which are rejected above.
        }
        throw Status.INVALID_ARGUMENT.withDescription("Job ID must be a UUID").asRuntimeException();
    }

    private static ImportJob toProto(ImportJobRepository.Job job) {
        var result = ImportJob.newBuilder().setJobId(job.jobId().toString())
            .setMode(ImportMode.valueOf(job.importMode())).setStatus(ImportJobStatus.valueOf(job.status()))
            .setForceOverwrite(job.forceOverwrite()).setCreatedAt(timestamp(job.createdAt()))
            .setUploadExpiresAt(timestamp(job.uploadExpiresAt())).setRowsRead(job.rowsRead())
            .setRowsApplied(job.rowsApplied()).setRowsUnchanged(job.rowsUnchanged())
            .setRowsRejected(job.rowsRejected()).setFramesRetired(job.framesRetired());
        if (job.finishedAt() != null) {
            result.setFinishedAt(timestamp(job.finishedAt()));
        }
        if (job.failureCode() != null) {
            result.setFailureCode(job.failureCode());
        }
        return result.build();
    }

    private static Timestamp timestamp(OffsetDateTime value) {
        return Timestamp.newBuilder().setSeconds(value.toEpochSecond()).setNanos(value.getNano()).build();
    }

    private static <T> void reply(StreamObserver<T> response, T result) {
        response.onNext(result);
        response.onCompleted();
    }
}
